/**
 * Device-level lock tracking, independent of any booking.
 *
 * `rental_tracking_logs` answers "what happened on booking #123". These tables
 * answer "where is this piece of equipment right now", which still needs to be
 * correct when a PIN cannot be matched to a booking (key/thumbturn use, an
 * expired code, a break-in attempt).
 *
 * Shared by igloohome-webhook and the sync-lock-activity poller so both paths
 * converge on the same state, deduplicated by a unique index.
 */

import { type LockActivityEvent, redactPins } from "./iglooActivity.ts";
import { resolveOrderIdByPin } from "./lockEventState.ts";

// deno-lint-ignore no-explicit-any
type SupabaseClient = any;

export type RecordedEvent = {
  event: LockActivityEvent;
  deviceId: string;
  orderId: number | null;
};

export type RecordResult = {
  recorded: RecordedEvent[];
  stored: number;
  skippedDuplicates: number;
};

export function defaultDeviceId(): string | null {
  return Deno.env.get("IGLOOHOME_LOCK_ID") || Deno.env.get("IGLOOHOME_DEVICE_ID") || null;
}

export function defaultBridgeId(): string | null {
  return Deno.env.get("IGLOOHOME_BRIDGE_ID") || null;
}

export async function ensureBridge(
  supabase: SupabaseClient,
  bridgeId: string | null,
): Promise<void> {
  if (!bridgeId) return;
  const { error } = await supabase.from("lock_bridges").upsert(
    { bridge_id: bridgeId, last_event_at: new Date().toISOString() },
    { onConflict: "bridge_id" },
  );
  if (error) console.error("[lockDeviceState] ensureBridge failed:", error.message);
}

/**
 * Register hardware the first time we hear from it, so adding a second lock is
 * plug-and-play — map it to a piece of equipment afterwards in the admin UI.
 */
export async function ensureDevice(
  supabase: SupabaseClient,
  deviceId: string,
  bridgeId: string | null,
): Promise<Record<string, unknown> | null> {
  await ensureBridge(supabase, bridgeId);

  const columns = "device_id, label, bridge_id, current_state, state_changed_at, equipment_id";
  const { data: existing } = await supabase
    .from("lock_devices")
    .select(columns)
    .eq("device_id", deviceId)
    .maybeSingle();

  if (existing) {
    if (bridgeId && existing.bridge_id !== bridgeId) {
      await supabase.from("lock_devices").update({ bridge_id: bridgeId }).eq(
        "device_id",
        deviceId,
      );
    }
    return existing;
  }

  const { data: inserted, error } = await supabase
    .from("lock_devices")
    .insert({ device_id: deviceId, bridge_id: bridgeId, current_state: "unknown" })
    .select(columns)
    .maybeSingle();
  if (error) console.error("[lockDeviceState] ensureDevice insert failed:", error.message);
  return inserted ?? null;
}

/**
 * Persist activity events against their device and roll the device's current
 * state forward. Returns only the events that were new, so callers do not
 * re-notify on a redelivery.
 */
export async function recordDeviceEvents(
  supabase: SupabaseClient,
  events: LockActivityEvent[],
  opts: { deviceId?: string | null; bridgeId?: string | null } = {},
): Promise<RecordResult> {
  const fallbackDeviceId = opts.deviceId || defaultDeviceId();
  const bridgeId = opts.bridgeId || defaultBridgeId();

  const ordered = [...events].sort(
    (a, b) => new Date(a.eventTimestamp).getTime() - new Date(b.eventTimestamp).getTime(),
  );

  const recorded: RecordedEvent[] = [];
  const latestPerDevice = new Map<string, LockActivityEvent>();
  const deviceCache = new Map<string, Record<string, unknown> | null>();
  let stored = 0;
  let skippedDuplicates = 0;

  for (const event of ordered) {
    const deviceId = event.deviceId || fallbackDeviceId;
    if (!deviceId) {
      console.warn("[lockDeviceState] Event with no resolvable device id; skipping");
      continue;
    }
    if (!deviceCache.has(deviceId)) {
      deviceCache.set(deviceId, await ensureDevice(supabase, deviceId, bridgeId));
    }
    const device = deviceCache.get(deviceId) ?? null;

    // The PIN is used in memory to match a booking, then stripped before the
    // payload is stored. It is never written to the table or to the logs.
    const orderId = await resolveOrderIdByPin(supabase, event.pinCode, event.eventTimestamp);

    const { error } = await supabase.from("lock_device_events").insert({
      device_id: deviceId,
      bridge_id: bridgeId,
      event_kind: event.eventType,
      log_type: event.logType,
      occurred_at: event.eventTimestamp,
      order_id: orderId,
      pin_matched: Boolean(event.pinCode && orderId),
      key_id: event.keyId,
      operation_id: event.operationId,
      raw: redactPins(event.raw),
    });

    if (error) {
      // 23505 means an earlier delivery or poll already ingested this entry.
      if (error.code === "23505") skippedDuplicates += 1;
      else console.error("[lockDeviceState] event insert failed:", error.message);
      continue;
    }

    stored += 1;
    recorded.push({ event: { ...event, raw: {} }, deviceId, orderId });

    if (event.eventType === "breakin") {
      await supabase
        .from("lock_devices")
        .update({ last_breakin_at: event.eventTimestamp })
        .eq("device_id", deviceId);
      continue;
    }

    // Entries can arrive batched and out of order; never let a stale entry
    // overwrite a more recent known state.
    const known = latestPerDevice.get(deviceId);
    const previousMs = known
      ? new Date(known.eventTimestamp).getTime()
      : device?.state_changed_at
      ? new Date(String(device.state_changed_at)).getTime()
      : -Infinity;
    if (new Date(event.eventTimestamp).getTime() >= previousMs) {
      latestPerDevice.set(deviceId, event);
    }
  }

  for (const [deviceId, latest] of latestPerDevice) {
    const { error } = await supabase
      .from("lock_devices")
      .update({
        current_state: latest.eventType === "lock" ? "locked" : "unlocked",
        state_changed_at: latest.eventTimestamp,
        last_event_at: latest.eventTimestamp,
      })
      .eq("device_id", deviceId);
    if (error) console.error("[lockDeviceState] state update failed:", error.message);
  }

  return { recorded, stored, skippedDuplicates };
}

/**
 * Lock-event state machine for self-pickup rentals.
 * - First unlock at/after booking start → Mark Rented (status Delivered + rented_out_at)
 * - Lock at/after scheduled end → Mark Returned (status pending_checklist + returned_at)
 * - Grace-hour sweep closes rentals whose last lock fell in/after the end window
 */

import { BOOKING_WINDOW_COLUMNS, getBookingWindow } from "./pinTiming.ts";
import { isDeliveryBooking } from "./deliveryBooking.ts";

// deno-lint-ignore no-explicit-any
type SupabaseClient = any;

export type LockEventInput = {
  orderId: number;
  eventType: "unlock" | "lock" | "breakin";
  eventTimestamp: string;
  notes?: string;
};

function isCustomerPickupBooking(booking: Record<string, unknown>): boolean {
  if (isDeliveryBooking(booking)) return false;
  const plan = (booking.plan || {}) as Record<string, unknown>;
  if (plan.customer_pickup === true) return true;
  const id = Number(plan.id);
  return id === 2 || id === 5;
}

async function invokeNotify(
  supabase: SupabaseClient,
  functionName: string,
  body: Record<string, unknown>,
): Promise<void> {
  const base = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!base || !key) {
    console.error(`[lockEventState] Missing SUPABASE_URL/SERVICE_ROLE_KEY for ${functionName}`);
    return;
  }
  try {
    const res = await fetch(`${base}/functions/v1/${functionName}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${key}`,
      },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      console.error(`[lockEventState] ${functionName} failed:`, await res.text());
    }
  } catch (err) {
    console.error(`[lockEventState] ${functionName} exception:`, err);
  }
}

/** Insert a tracking log, ignoring unique-constraint duplicates. Returns true if inserted. */
export async function insertTrackingLog(
  supabase: SupabaseClient,
  event: LockEventInput,
): Promise<boolean> {
  const { error } = await supabase.from("rental_tracking_logs").insert({
    order_id: event.orderId,
    event_type: event.eventType,
    event_timestamp: event.eventTimestamp,
    api_sync_timestamp: new Date().toISOString(),
    notes: event.notes || `${event.eventType} event via lock sync`,
  });
  if (error) {
    // Unique violation = already ingested
    if (error.code === "23505" || String(error.message || "").includes("duplicate")) {
      return false;
    }
    console.error(`[lockEventState] insertTrackingLog error:`, error);
    return false;
  }
  return true;
}

async function markRented(
  supabase: SupabaseClient,
  booking: Record<string, unknown>,
  eventTimestamp: string,
): Promise<boolean> {
  if (booking.rented_out_at) return false;
  const { error } = await supabase
    .from("bookings")
    .update({
      rented_out_at: eventTimestamp,
      status: "Delivered",
    })
    .eq("id", booking.id)
    .is("rented_out_at", null);
  if (error) {
    console.error(`[lockEventState] markRented failed for #${booking.id}:`, error);
    return false;
  }
  console.log(`[lockEventState] Booking #${booking.id} marked Rented at ${eventTimestamp}`);

  if (!booking.rental_started_notified_at) {
    await invokeNotify(supabase, "send-rental-started", {
      order_id: booking.id,
      unlock_timestamp: eventTimestamp,
    });
  }
  return true;
}

async function markReturned(
  supabase: SupabaseClient,
  booking: Record<string, unknown>,
  eventTimestamp: string,
): Promise<boolean> {
  if (!booking.rented_out_at || booking.returned_at) return false;
  const { error } = await supabase
    .from("bookings")
    .update({
      returned_at: eventTimestamp,
      status: "pending_checklist",
    })
    .eq("id", booking.id)
    .is("returned_at", null)
    .not("rented_out_at", "is", null);
  if (error) {
    console.error(`[lockEventState] markReturned failed for #${booking.id}:`, error);
    return false;
  }
  console.log(`[lockEventState] Booking #${booking.id} marked Returned at ${eventTimestamp}`);

  if (!booking.return_notified_at) {
    await invokeNotify(supabase, "send-return-confirmation", {
      order_id: booking.id,
      lock_event_timestamp: eventTimestamp,
    });
  }
  return true;
}

/**
 * Apply a single lock/unlock event to the matching booking.
 * Returns a short action description for logging.
 */
export async function applyLockEvent(
  supabase: SupabaseClient,
  event: LockEventInput,
): Promise<string> {
  const inserted = await insertTrackingLog(supabase, event);

  // Break-ins belong on the booking timeline but never move rental state.
  if (event.eventType === "breakin") {
    return inserted ? "logged_breakin" : "duplicate_breakin";
  }

  const { data: booking, error } = await supabase
    .from("bookings")
    .select(
      `id, status, plan, addons, ${BOOKING_WINDOW_COLUMNS}, rented_out_at, returned_at, rental_started_notified_at, return_notified_at`,
    )
    .eq("id", event.orderId)
    .single();

  if (error || !booking) {
    return inserted ? "logged_no_booking" : "skipped";
  }

  if (!isCustomerPickupBooking(booking)) {
    return inserted ? "logged_not_self_pickup" : "skipped";
  }

  const window = getBookingWindow(booking);
  const eventMs = new Date(event.eventTimestamp).getTime();
  if (Number.isNaN(eventMs)) return "invalid_timestamp";

  if (event.eventType === "unlock") {
    if (eventMs >= window.startMs && !booking.rented_out_at) {
      await markRented(supabase, booking, event.eventTimestamp);
      return "marked_rented";
    }
    return inserted ? "logged_unlock" : "duplicate_unlock";
  }

  // lock event
  if (
    eventMs >= window.endMs &&
    booking.rented_out_at &&
    !booking.returned_at
  ) {
    await markReturned(supabase, booking, event.eventTimestamp);
    return "marked_returned";
  }
  return inserted ? "logged_lock" : "duplicate_lock";
}

/**
 * After ingesting events, close any self-pickup rental whose grace hour has
 * passed and that has a lock event at/after the scheduled end but no returned_at.
 */
export async function sweepGraceHourReturns(
  supabase: SupabaseClient,
  now: Date = new Date(),
): Promise<number> {
  const { data: candidates, error } = await supabase
    .from("bookings")
    .select(
      `id, status, plan, addons, ${BOOKING_WINDOW_COLUMNS}, rented_out_at, returned_at, rental_started_notified_at, return_notified_at`,
    )
    .not("rented_out_at", "is", null)
    .is("returned_at", null)
    .not("status", "in", '("Cancelled","Completed","flagged")');

  if (error || !candidates?.length) {
    if (error) console.error("[lockEventState] sweepGraceHourReturns query error:", error);
    return 0;
  }

  let closed = 0;
  const nowMs = now.getTime();

  for (const booking of candidates) {
    if (!isCustomerPickupBooking(booking)) continue;
    const window = getBookingWindow(booking);
    if (nowMs < window.graceEndMs) continue;

    const { data: lockEvent } = await supabase
      .from("rental_tracking_logs")
      .select("event_timestamp")
      .eq("order_id", booking.id)
      .eq("event_type", "lock")
      .gte("event_timestamp", new Date(window.endMs).toISOString())
      .order("event_timestamp", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (!lockEvent?.event_timestamp) continue;

    const ok = await markReturned(supabase, booking, lockEvent.event_timestamp);
    if (ok) closed += 1;
  }

  return closed;
}

/**
 * Resolve order_id from a PIN by looking up active rental_access_codes whose
 * validity window covers the event timestamp.
 */
export async function resolveOrderIdByPin(
  supabase: SupabaseClient,
  pinCode: string | null,
  eventTimestamp: string,
): Promise<number | null> {
  if (!pinCode) return null;
  const { data, error } = await supabase
    .from("rental_access_codes")
    .select("order_id, start_time, end_time, status")
    .eq("access_pin", pinCode)
    .in("status", ["active", "expired", "used"])
    .order("created_at", { ascending: false })
    .limit(10);

  if (error || !data?.length) return null;

  const eventMs = new Date(eventTimestamp).getTime();
  for (const row of data) {
    const start = new Date(row.start_time).getTime();
    const end = new Date(row.end_time).getTime();
    // Allow a small buffer before start (early unlock attempts) and after end
    if (eventMs >= start - 60 * 60 * 1000 && eventMs <= end + 2 * 60 * 60 * 1000) {
      return Number(row.order_id);
    }
  }
  // Fallback: most recent matching PIN
  return Number(data[0].order_id);
}

/**
 * Booking time slot parsing, mirroring the SQL functions of the same name.
 *
 * Stored slots come in four shapes depending on which code path wrote the row: '6:00 AM',
 * '06:00:00', '06:00:00|08:00:00' and '08:00|17:00'. Anything that reasons about booking times
 * has to handle all four, and previously each caller handled a different subset.
 *
 * Prefer the typed bookings.*_window_start / *_window_end columns where they are available;
 * these helpers exist for rows written before those columns existed and for callers that only
 * have the text value to hand.
 *
 * Keep in sync with public.parse_clock_time and public.parse_booking_time_slot.
 */

export const BUSINESS_TIME_ZONE = "America/Denver";

export type ClockTime = { hour: number; minute: number; second: number };
export type TimeWindow = { start: ClockTime; end: ClockTime };

const TWELVE_HOUR = /^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)$/i;
const TWENTY_FOUR_HOUR = /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/;

/** Parses HH:mm, HH:mm:ss or h:mm AM/PM. Returns null for anything unrecognised. */
export function parseClockTime(value: string | null | undefined): ClockTime | null {
  if (typeof value !== "string") return null;
  const raw = value.trim();
  if (!raw) return null;

  const twelve = TWELVE_HOUR.exec(raw);
  if (twelve) {
    let hour = parseInt(twelve[1], 10) % 12;
    if (twelve[4].toUpperCase() === "PM") hour += 12;
    const minute = parseInt(twelve[2], 10);
    const second = twelve[3] ? parseInt(twelve[3], 10) : 0;
    if (minute > 59 || second > 59) return null;
    return { hour, minute, second };
  }

  const twentyFour = TWENTY_FOUR_HOUR.exec(raw);
  if (twentyFour) {
    const hour = parseInt(twentyFour[1], 10);
    const minute = parseInt(twentyFour[2], 10);
    const second = twentyFour[3] ? parseInt(twentyFour[3], 10) : 0;
    if (hour > 23 || minute > 59 || second > 59) return null;
    return { hour, minute, second };
  }

  return null;
}

function toMinutes(t: ClockTime): number {
  return t.hour * 60 + t.minute;
}

/**
 * Normalises any stored slot into a start/end window.
 *
 * @param spanMinutes How long a single-valued slot lasts. Pass 0 for services whose slot is an
 *   instant rather than a window (hourly self-pickup stores a collection time and a return-by
 *   deadline, not a window).
 */
export function parseBookingTimeSlot(
  slot: string | null | undefined,
  spanMinutes = 120,
): TimeWindow | null {
  if (typeof slot !== "string") return null;
  const raw = slot.trim();
  if (!raw) return null;

  if (raw.includes("|")) {
    const [leftRaw, rightRaw] = raw.split("|");
    const start = parseClockTime(leftRaw);
    const end = parseClockTime(rightRaw);
    if (!start || !end) return null;
    return { start, end };
  }

  const start = parseClockTime(raw);
  if (!start) return null;

  const span = Math.max(spanMinutes ?? 0, 0);
  if (span === 0) return { start, end: { ...start } };

  const endMinutes = toMinutes(start) + span;
  // A late slot plus its span can run past midnight, which would leave end before start and
  // break every overlap test. Clamp to the end of the day instead.
  if (endMinutes >= 24 * 60) {
    return { start, end: { hour: 23, minute: 59, second: 59 } };
  }
  return {
    start,
    end: { hour: Math.floor(endMinutes / 60), minute: endMinutes % 60, second: 0 },
  };
}

/** Minutes the given zone is offset from UTC at a particular instant (negative west of UTC). */
function zoneOffsetMinutes(instant: Date, timeZone: string): number {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hour12: false,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(instant);

  const field = (type: string) => Number(parts.find((p) => p.type === type)?.value ?? "0");
  // Intl renders midnight as hour 24 in some runtimes; normalise it.
  const hour = field("hour") % 24;

  const asIfUtc = Date.UTC(
    field("year"),
    field("month") - 1,
    field("day"),
    hour,
    field("minute"),
    field("second"),
  );
  return (asIfUtc - instant.getTime()) / 60000;
}

/**
 * Converts a wall-clock date and time in the business timezone into a real UTC instant.
 *
 * The offset depends on the instant we are trying to find, so this resolves it in two passes:
 * guess using the offset at the naive instant, then re-check the offset at that result. That
 * matters because America/Denver is UTC-7 in winter and UTC-6 in summer, and the previous
 * implementation hardcoded a single offset.
 */
export function businessWallTimeToUtc(
  dateIso: string,
  time: ClockTime,
  timeZone: string = BUSINESS_TIME_ZONE,
): Date | null {
  const dateMatch = /^(\d{4})-(\d{2})-(\d{2})/.exec(dateIso ?? "");
  if (!dateMatch) return null;

  const naive = Date.UTC(
    Number(dateMatch[1]),
    Number(dateMatch[2]) - 1,
    Number(dateMatch[3]),
    time.hour,
    time.minute,
    time.second,
  );

  const firstOffset = zoneOffsetMinutes(new Date(naive), timeZone);
  let resolved = new Date(naive - firstOffset * 60000);

  const secondOffset = zoneOffsetMinutes(resolved, timeZone);
  if (secondOffset !== firstOffset) {
    resolved = new Date(naive - secondOffset * 60000);
  }
  return resolved;
}

/** Formats a ClockTime as HH:mm:ss, matching the Postgres `time` text representation. */
export function formatClockTime(time: ClockTime): string {
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(time.hour)}:${pad(time.minute)}:${pad(time.second)}`;
}
